exercises.solution:
function myAll(iterable) {
  return new Promise((resolve, reject) => {
    const items = Array.from(iterable);
    if (items.length === 0) return resolve([]);
    const results = new Array(items.length);
    let remaining = items.length;
    let settled = false;
    items.forEach((item, i) => {
      Promise.resolve(item).then(
        v => {
          if (settled) return;
          results[i] = v;
          if (--remaining === 0) { settled = true; resolve(results); }
        },
        e => {
          if (settled) return;
          settled = true;
          reject(e);
        }
      );
    });
  });
}

const delay = (v, ms) => new Promise(r => setTimeout(() => r(v), ms));

(async () => {
  console.log('ordered:', (await myAll([delay('a', 30), 'b', delay('c', 10)])).join(','));
  console.log('empty:', JSON.stringify(await myAll([])));
  console.log('thenable:', (await myAll([{ then(res) { res('t'); } }]))[0]);
  try {
    await myAll([delay('x', 10), Promise.reject(new Error('boom')), delay('y', 50)]);
    console.log('should not print');
  } catch (e) {
    console.log('rejected:', e.message);
  }
})();

exercises.prompt:
Implement `pLimit(concurrency)` returning a `limited(fn)` wrapper: at most `concurrency` task-functions run at once; extras queue in FIFO order. Each `limited(fn)` call returns a promise of `fn()`'s result, and rejections propagate.

```js
function pLimit(concurrency) {
  // ...
}

let running = 0, maxRunning = 0;
const task = (id, ms) => () => new Promise(resolve => {
  running++;
  maxRunning = Math.max(maxRunning, running);
  setTimeout(() => { running--; resolve(`task${id}`); }, ms);
});

(async () => {
  const limit = pLimit(2);
  const results = await Promise.all([1, 2, 3, 4, 5, 6].map(i => limit(task(i, 30))));
  console.log('results:', results.join(','));
  console.log('max concurrent:', maxRunning);
  console.log('limit respected:', maxRunning <= 2);
})();
```

Expected solution output:
```
results: task1,task2,task3,task4,task5,task6
max concurrent: 2
limit respected: true
```

