exercises.prompt:
Implement `retry(fn, { attempts, baseDelayMs })`: call `fn()`; on failure, if attempts remain, wait `baseDelayMs * 2^attemptIndex` (attemptIndex 0-based) and retry; when attempts are exhausted, throw the last error. `fn` may be sync or async.

```js
async function retry(fn, { attempts = 3, baseDelayMs = 50 } = {}) {
  // ...
}

let calls = 0;
async function flaky() {
  calls++;
  console.log(`attempt ${calls}`);
  if (calls < 3) throw new Error('boom');
  return 'recovered';
}

(async () => {
  const start = Date.now();
  const out = await retry(flaky, { attempts: 5, baseDelayMs: 50 });
  const elapsed = Date.now() - start;
  console.log(`result: ${out} | attempts used: ${calls}`);
  // backoff waited ~50ms then ~100ms; timers never fire early, so allow slop:
  console.log('backoff respected:', elapsed >= 120);

  let c2 = 0;
  try {
    await retry(() => { c2++; throw new Error('dead'); }, { attempts: 3, baseDelayMs: 10 });
    console.log('should not print');
  } catch (e) {
    console.log(`gave up after ${c2} attempts: ${e.message}`);
  }
})();
```

Expected solution output:
```
attempt 1
attempt 2
attempt 3
result: recovered | attempts used: 3
backoff respected: true
gave up after 3 attempts: dead
```

