exercises.solution:
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

async function retry(fn, { attempts = 3, baseDelayMs = 50 } = {}) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (e) {
      lastError = e;
      if (i < attempts - 1) await sleep(baseDelayMs * 2 ** i);
    }
  }
  throw lastError;
}

let calls = 0;
async function flaky() {
  calls++;
  console.log(`attempt ${calls}`);
  if (calls < 3) throw new Error('boom');
  return 'recovered';
}

(async () => {
  const start = Date.now();
  const out = await retry(flaky, { attempts: 5, baseDelayMs: 50 });
  const elapsed = Date.now() - start;
  console.log(`result: ${out} | attempts used: ${calls}`);
  console.log('backoff respected:', elapsed >= 120);

  let c2 = 0;
  try {
    await retry(() => { c2++; throw new Error('dead'); }, { attempts: 3, baseDelayMs: 10 });
    console.log('should not print');
  } catch (e) {
    console.log(`gave up after ${c2} attempts: ${e.message}`);
  }
})();

exercises.prompt:
Wire an `AbortController` into a cancellable async task. The demo aborts a 5-second task after 50ms and catches the abort, then shows `AbortSignal.timeout` doing the same job declaratively.

```js
function cancellableTask(signal, ms) {
  return new Promise((resolve, reject) => {
    if (signal.aborted) return reject(signal.reason);
    const t = setTimeout(() => resolve('finished'), ms);
    signal.addEventListener('abort', () => {
      clearTimeout(t);
      reject(signal.reason);
    }, { once: true });
  });
}

(async () => {
  const c = new AbortController();
  const p = cancellableTask(c.signal, 5000);
  setTimeout(() => c.abort(new DOMException('user cancelled', 'AbortError')), 50);
  try {
    await p;
    console.log('should not print');
  } catch (e) {
    console.log('manual abort caught:', e.name, '-', e.message);
  }

  try {
    await cancellableTask(AbortSignal.timeout(50), 5000);
    console.log('should not print');
  } catch (e) {
    console.log('timeout signal caught:', e.name);
  }
})();
```

Expected solution output:
```
manual abort caught: AbortError - user cancelled
timeout signal caught: TimeoutError
```

